files.content:
'use strict';
const assert = require('node:assert');
const api = require('./solution');
assert.deepStrictEqual(Object.keys(api), ['stableViewportHeight']);
const { stableViewportHeight } = api;

assert.strictEqual(stableViewportHeight([10]), 10);
assert.strictEqual(stableViewportHeight([10, 2, 30]), 10);
assert.strictEqual(stableViewportHeight([100, 2, 20, 3]), 11.5);
assert.strictEqual(stableViewportHeight([2.5, 1.5, 2.5, 9.25]), 2.5);
assert.strictEqual(stableViewportHeight([7, 7, 7]), 7);
const samples = Object.freeze([200, 50, 100, 25]);
assert.strictEqual(stableViewportHeight(samples), 75);
assert.deepStrictEqual(samples, [200, 50, 100, 25]);
for (const bad of [null, {}, '10', [], [0], [-1], [NaN], [Infinity], ['2'], [1, null]]) {
  assert.throws(() => stableViewportHeight(bad), TypeError);
}

